/**
 * RFC 7807 Problem Details for HTTP APIs
 * https://datatracker.ietf.org/doc/html/rfc7807
 */

/**
 * Problem Details interface following RFC 7807
 */
export interface ProblemDetails {
  /**
   * A URI reference that identifies the problem type
   * This URI should provide human-readable documentation for the problem type
   */
  type: string

  /**
   * A short, human-readable summary of the problem type
   */
  title: string

  /**
   * The HTTP status code generated by the origin server
   */
  status: number

  /**
   * A human-readable explanation specific to this occurrence of the problem
   */
  detail?: string

  /**
   * A URI reference that identifies the specific occurrence of the problem
   */
  instance?: string

  /**
   * Additional members for extension
   */
  [key: string]: unknown
}

/**
 * Builder class for creating RFC 7807 Problem Details responses
 */
export class ProblemDetailsBuilder {
  private problemDetails: ProblemDetails

  private constructor(type: string, title: string, status: number) {
    this.problemDetails = {
      type,
      title,
      status,
    }
  }

  /**
   * Creates a new ProblemDetailsBuilder instance
   * @param type - URI reference identifying the problem type
   * @param title - Short summary of the problem type
   * @param status - HTTP status code
   */
  static create(type: string, title: string, status: number): ProblemDetailsBuilder {
    return new ProblemDetailsBuilder(type, title, status)
  }

  /**
   * Sets the detail field
   * @param detail - Human-readable explanation of this specific occurrence
   */
  withDetail(detail: string): ProblemDetailsBuilder {
    this.problemDetails.detail = detail
    return this
  }

  /**
   * Sets the instance field
   * @param instance - URI reference identifying this specific occurrence
   */
  withInstance(instance: string): ProblemDetailsBuilder {
    this.problemDetails.instance = instance
    return this
  }

  /**
   * Adds custom extension fields
   * @param key - Extension field name
   * @param value - Extension field value
   */
  withExtension(key: string, value: unknown): ProblemDetailsBuilder {
    this.problemDetails[key] = value
    return this
  }

  /**
   * Builds and returns the ProblemDetails object
   */
  build(): ProblemDetails {
    return this.problemDetails
  }
}
